package com.cowave.search.history.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.index.Indexed
import org.springframework.data.mongodb.core.mapping.Document

@Document(collection = "index_history")
data class IndexHistory(
    @Id
    val id: String = ObjectId.get().toHexString(),
    @Indexed
    val clusterId: String,
    val collectionId: String,
    val index: String,
    val jobType: String,
    val startTime: Long,
    var endTime: Long? = null,
    val autoRun: Boolean = false,
    var status: String,
    var docSize: String? = null,
    var store: String? = null,
)

package com.cowave.search.history.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.index.CompoundIndex
import org.springframework.data.mongodb.core.index.Indexed
import org.springframework.data.mongodb.core.mapping.Document

@Document(collection = "index_status")
@CompoundIndex(def = "{'clusterId': 1, 'collectionId': 1}", unique = true)
data class IndexStatus(
    @Id
    val id: String = ObjectId.get().toHexString(),
    @Indexed
    val clusterId: String,
    var collectionId: String,
    var index: String,
    val startTime: Long,
    var status: String,
    var step: String? = null,
    var jobId: String? = null,
)

package com.cowave.search.dynamicindex.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.mapping.Document

@Document(collection = "dynamic_index")
data class DynamicIndexInfo(
    @Id
    val id: String = ObjectId.get().toHexString(),
    var bundleQueue: String,
    var bundleServer: String,
    var scheme: String,
    var ip: String,
    var port: String,
    var stateEndPoint: String? = null,
    var consumeEndPoint: String? = null,
)
